import heapq

def stable_toposort(graph):
    nodes = list(graph.keys())
    position = {node: i for i, node in enumerate(nodes)}
    dependents = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for node, deps in graph.items():
        seen = set()
        count = 0
        for dep in deps:
            if dep not in position:
                raise ValueError(f"missing dependency: {dep!r}")
            if dep in seen:
                continue
            seen.add(dep)
            dependents[dep].append(node)
            count += 1
        indegree[node] = count

    ready = [(position[node], node) for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        _, node = heapq.heappop(ready)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, (position[dependent], dependent))

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def schema_drift(expected, actual):
    def leaf_paths(node, prefix):
        if not isinstance(node, dict):
            return [prefix]
        if not node:
            return [prefix]

        paths = []
        for key, value in node.items():
            path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                paths.extend(leaf_paths(value, path))
            else:
                paths.append(path)
        return paths

    def compare(e, a, prefix=""):
        drifts = []
        e_keys = set(e)
        a_keys = set(a)

        for key in sorted(e_keys - a_keys):
            path = f"{prefix}.{key}" if prefix else key
            drifts.extend(leaf_paths(e[key], path))

        for key in sorted(a_keys - e_keys):
            path = f"{prefix}.{key}" if prefix else key
            drifts.extend(leaf_paths(a[key], path))

        for key in sorted(e_keys & a_keys):
            path = f"{prefix}.{key}" if prefix else key
            ev = e[key]
            av = a[key]

            if isinstance(ev, dict) and isinstance(av, dict):
                drifts.extend(compare(ev, av, path))
            elif isinstance(ev, dict) or isinstance(av, dict):
                drifts.append(path)
            elif ev != av:
                drifts.append(path)

        return drifts

    return sorted(set(compare(expected, actual)))

def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_rows = 0

    for partition, row_count in items:
        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            batches.append([(partition, row_count)])
        else:
            if current_rows + row_count > max_rows:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            current_batch.append((partition, row_count))
            current_rows += row_count

    if current_batch:
        batches.append(current_batch)

    return batches

def committable_windows(events, watermark):
    result = {}
    for event in events:
        if event["event_time"] <= watermark:
            continue
        window = event["window"]
        if window not in result:
            result[window] = []
        result[window].append(event["value"])
    return result

